VALUES ('transfer_workflows', '[{\"id\":\"wf-almuslim-factory\",\"name\":\"Al-Muslim Smart Factory Rule (Intelligent 1-Step Approval)\",\"description\":\"Auto-adapts: Same Floor ➔ Floor Manager | Cross Floor ➔ Destination Floor | Cross Unit ➔ Destination Unit Admin. Central Admin can approve ANY stage anytime!\",\"isDefault\":true,\"isSmartRouting\":true,\"scope\":{},\"requireDocument\":false,\"sequential\":true,\"status\":\"ACTIVE\",\"levels\":[{\"level\":1,\"title\":\"Factory In-Charge / Admin Approval\",\"approverType\":\"DEST_LOCATION\",\"approverRole\":\"\",\"approverUserId\":\"\",\"description\":\"Auto-adapts: Floor Manager (same floor), Receiving Floor (cross-floor), Unit Admin (cross-unit). Central Admin has full override.\",\"required\":true}],\"createdBy\":\"usr-super-admin\",\"createdAt\":\"2026-09-19T11:22:30.066Z\",\"updatedBy\":\"usr-super-admin\",\"updatedAt\":\"2026-09-19T11:32:00.042Z\"},{\"id\":\"wf-fast-track\",\"name\":\"Option A: Admin Direct Authorization (Fast-Track)\",\"description\":\"Emergency production line balancing approved directly by Super Admin.\",\"isDefault\":false,\"scope\":{},\"requireDocument\":false,\"sequential\":true,\"status\":\"ACTIVE\",\"levels\":[{\"level\":1,\"title\":\"Super Admin / Maintenance Admin\",\"approverType\":\"ADMIN\",\"description\":\"Direct one-step authorization.\"}],\"createdBy\":\"usr-super-admin\",\"createdAt\":\"2026-09-19T11:22:30.066Z\"},{\"id\":\"wf-default\",\"name\":\"Standard Factory Transfer (Source → Dest → Admin)\",\"description\":\"Standard 3-stage relocation protocol for sewing and finishing machinery.\",\"isDefault\":false,\"scope\":{},\"requireDocument\":true,\"sequential\":true,\"status\":\"ACTIVE\",\"levels\":[{\"level\":1,\"title\":\"Source Floor In-Charge Release\",\"approverType\":\"SOURCE_LOCATION\",\"description\":\"Release equipment from source line.\"},{\"level\":2,\"title\":\"Destination Floor In-Charge Acceptance\",\"approverType\":\"DEST_LOCATION\",\"description\":\"Accept machine at target destination.\"},{\"level\":3,\"title\":\"Central Maintenance Admin Authorization\",\"approverType\":\"ADMIN\",\"description\":\"Final gate pass sign-off and inventory update.\"}],\"createdBy\":\"usr-super-admin\",\"createdAt\":\"2026-09-19T11:22:30.066Z\"},{\"id\":\"wf-fast-track\",\"name\":\"Urgent Maintenance Admin Approval (Fast-Track)\",\"description\":\"Emergency production line balancing approved directly by Super Admin.\",\"isDefault\":false,\"scope\":{},\"requireDocument\":false,\"sequential\":true,\"status\":\"ACTIVE\",\"levels\":[{\"level\":1,\"title\":\"Super Admin / Maintenance Admin\",\"approverType\":\"ADMIN\",\"description\":\"Direct one-step authorization.\"}],\"createdBy\":\"usr-super-admin\",\"createdAt\":\"2026-09-19T11:22:30.066Z\"},{\"id\":\"wf-heavy-utility\",\"name\":\"Heavy Utility & Cutting Equipment Relocation (4 Levels)\",\"description\":\"High-risk equipment transfer requiring manager and floor safety sign-offs.\",\"isDefault\":false,\"scope\":{\"categoryId\":\"cat-4\"},\"requireDocument\":true,\"sequential\":true,\"status\":\"ACTIVE\",\"levels\":[{\"level\":1,\"title\":\"Source Floor Engineer\",\"approverType\":\"SOURCE_LOCATION\",\"description\":\"Mechanical/electrical disconnection audit.\"},{\"level\":2,\"title\":\"Destination Plant In-Charge\",\"approverType\":\"DEST_LOCATION\",\"description\":\"Utility connection and safety inspection.\"},{\"level\":3,\"title\":\"Chief Maintenance Manager\",\"approverType\":\"MAINTENANCE_MANAGER\",\"description\":\"Asset compliance & overhaul approval.\"},{\"level\":4,\"title\":\"General Admin Sign-off\",\"approverType\":\"ADMIN\",\"description\":\"Live location database update.\"}],\"createdBy\":\"usr-super-admin\",\"createdAt\":\"2026-09-19T11:22:30.066Z\"}]', 5, NOW()) 
