VALUES ('documents', '[{\"id\":\"fld-manuals\",\"name\":\"Machine Operation Manuals\",\"type\":\"folder\",\"parentId\":null,\"access\":\"Maintenance Team\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"USER\",\"role-super-admin\",\"role-admin\",\"role-manager\",\"role-user\"],\"description\":\"Technical instruction manuals, parts catalogs, and manufacturer machinery handbooks.\",\"createdAt\":\"2026-08-01T10:00:00Z\",\"createdByName\":\"Engr. Tanvir Ahmed\"},{\"id\":\"fld-sops\",\"name\":\"Standard Operating Procedures (SOPs)\",\"type\":\"folder\",\"parentId\":null,\"access\":\"Engineers\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"role-super-admin\",\"role-admin\",\"role-manager\"],\"description\":\"Official factory SOPs, quality protocols, lubrication guidelines, and engineering checklists.\",\"createdAt\":\"2026-08-02T11:00:00Z\",\"createdByName\":\"Engr. Delwar Hossain\"},{\"id\":\"fld-portals\",\"name\":\"Maintenance Portals & Web Links\",\"type\":\"folder\",\"parentId\":null,\"access\":\"Admin + Manager\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"role-super-admin\",\"role-admin\",\"role-manager\"],\"description\":\"Web dashboards, machinery vendor portals, and external cloud engineering repositories.\",\"createdAt\":\"2026-08-03T12:00:00Z\",\"createdByName\":\"Super Administrator\"},{\"id\":\"fld-schedules\",\"name\":\"Maintenance Schedules & Overhaul\",\"type\":\"folder\",\"parentId\":null,\"access\":\"All Staff\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"USER\",\"VIEWER\",\"role-super-admin\",\"role-admin\",\"role-manager\",\"role-user\",\"role-viewer\"],\"description\":\"Quarterly and monthly preventive maintenance calendars, parts replacement schedules.\",\"createdAt\":\"2026-08-04T13:00:00Z\",\"createdByName\":\"Engr. Delwar Hossain\"},{\"id\":\"fld-layouts\",\"name\":\"Factory Layouts & Schematics\",\"type\":\"folder\",\"parentId\":null,\"access\":\"Maintenance Team\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"USER\",\"role-super-admin\",\"role-admin\",\"role-manager\",\"role-user\"],\"description\":\"Machinery placement schematics, power line routes, and pneumatic pressure maps.\",\"createdAt\":\"2026-08-05T14:00:00Z\",\"createdByName\":\"Engr. Tanvir Ahmed\"},{\"id\":\"res-1\",\"name\":\"Machine Manual (Juki DDL-8700)\",\"type\":\"pdf\",\"parentId\":\"fld-manuals\",\"access\":\"Maintenance Team\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"USER\",\"role-super-admin\",\"role-admin\",\"role-manager\",\"role-user\"],\"fileName\":\"Juki_DDL_8700_Operation_Manual.pdf\",\"fileSize\":\"2.4 MB\",\"fileType\":\"application/pdf\",\"description\":\"Complete operational, threading and timing adjustment handbook for Juki Single Needle Lockstitch.\",\"content\":\"AL-MUSLIM GROUP TECHNICAL ARCHIVE\\nDOCUMENT: JUKI DDL-8700 OPERATION & MAINTENANCE MANUAL\\n\\n1. SPECIFICATIONS:\\n- Max Sewing Speed: 5,500 sti/min\\n- Needle: DBx1 (#14 #9-#18)\\n- Lubrication: Automatic oil pump\\n\\n2. TIMING ADJUSTMENT:\\n- Lower the needle bar to lowest point, align upper index line with bush edge.\\n- Hook point should align with needle center, 0.05mm clearance.\\n\\n3. DAILY MAINTENANCE:\\n- Check oil window clarity before shift start.\\n- Clean hook race with blower or brush every 8 hours.\\n\\nAl-Muslim Group Central Maintenance Department Archive.\",\"createdAt\":\"2026-08-10T09:00:00Z\",\"createdByName\":\"Engr. Tanvir Ahmed\"},{\"id\":\"res-4-1\",\"name\":\"Brother S-7200C Service Manual\",\"type\":\"pdf\",\"parentId\":\"fld-manuals\",\"access\":\"Maintenance Team\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"USER\",\"role-super-admin\",\"role-admin\",\"role-manager\",\"role-user\"],\"fileName\":\"Brother_S7200C_Direct_Drive_Service_Manual.pdf\",\"fileSize\":\"3.8 MB\",\"fileType\":\"application/pdf\",\"description\":\"Electronic direct drive direct motor service troubleshooting and error codes list.\",\"content\":\"BROTHER S-7200C ELECTRONIC DIRECT DRIVE SEWING MACHINE\\nTECHNICAL SERVICE GUIDE\\n\\nError Codes:\\n- E-01: Motor lock detected (check handwheel rotation & thread jam)\\n- E-02: Synchronizer optical sensor abnormal\\n- E-09: Overvoltage or supply fluctuation\\n\\nAl-Muslim Group Central Maintenance Department.\",\"createdAt\":\"2026-08-05T14:20:00Z\",\"createdByName\":\"Engr. Tanvir Ahmed\"},{\"id\":\"res-4-2\",\"name\":\"Pegasus M-700 Overlock Parts Book\",\"type\":\"excel\",\"parentId\":\"fld-manuals\",\"access\":\"Maintenance Team\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"USER\",\"role-super-admin\",\"role-admin\",\"role-manager\",\"role-user\"],\"fileName\":\"Pegasus_M700_Overlock_Parts_Catalog.xlsx\",\"fileSize\":\"1.2 MB\",\"fileType\":\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\",\"description\":\"Itemized spare parts numbers, knife assemblies, and looper timing specifications.\",\"content\":\"PART_NUMBER,PART_NAME,CATEGORY,LOCATION,PRICE_BDT\\nPG-701-01,Upper Knife,Cutting,Bin A-12,450\\nPG-701-02,Lower Carbide Knife,Cutting,Bin A-13,680\\nPG-702-01,Upper Looper,Looper,Bin B-04,1250\\nPG-702-02,Lower Looper,Looper,Bin B-05,1350\\nPG-703-01,Needle Plate 4-Thread,Gauge,Bin C-01,2100\",\"createdAt\":\"2026-08-08T16:45:00Z\",\"createdByName\":\"Md. Faruk Hossain\"},{\"id\":\"res-2\",\"name\":\"Maintenance SOP & Daily Checklist\",\"type\":\"word\",\"parentId\":\"fld-sops\",\"access\":\"Engineers\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"role-super-admin\",\"role-admin\",\"role-manager\"],\"fileName\":\"Standard_Operating_Procedure_Maintenance.docx\",\"fileSize\":\"850 KB\",\"fileType\":\"application/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"description\":\"Official Standard Operating Procedures for Garments Maintenance Engineers & Shift Technicians.\",\"content\":\"AL-MUSLIM GROUP GARMENTS APPAREL DIVISION\\nSTANDARD OPERATING PROCEDURE (SOP) - MACHINERY PREVENTIVE CARE\\n\\nObjective: Ensure 99.5\% line equipment uptime across all sewing lines.\\nScope: All mechanical, electrical, and pneumatic machinery.\\n\\nResponsibilities:\\n- Floor Maintenance Engineer: Daily audit of oil levels and motor temperature.\\n- Line Mechanic: Respond to breakdown calls within 3 minutes.\\n- Maintenance In-Charge: Sign off weekly lubrication log.\\n\\nApproved By: Chief Maintenance Director\",\"createdAt\":\"2026-08-12T11:30:00Z\",\"createdByName\":\"Engr. Delwar Hossain\"},{\"id\":\"res-3\",\"name\":\"Maintenance Portal & Knowledge Hub\",\"type\":\"url\",\"parentId\":\"fld-portals\",\"access\":\"Admin + Manager\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"role-super-admin\",\"role-admin\",\"role-manager\"],\"url\":\"https://portal.almuslim.com/maintenance\",\"description\":\"Central group enterprise engineering portal and vendor support documentation hub.\",\"createdAt\":\"2026-08-15T08:15:00Z\",\"createdByName\":\"Super Administrator\"},{\"id\":\"res-3-2\",\"name\":\"Juki Global Technical Support Portal\",\"type\":\"url\",\"parentId\":\"fld-portals\",\"access\":\"All Staff\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"USER\",\"VIEWER\",\"role-super-admin\",\"role-admin\",\"role-manager\",\"role-user\",\"role-viewer\"],\"url\":\"https://www.juki.co.jp/industrial_e/support_e/\",\"description\":\"Official manufacturer parts catalog search and electronic board firmware downloads.\",\"createdAt\":\"2026-08-16T09:00:00Z\",\"createdByName\":\"Super Administrator\"},{\"id\":\"res-5\",\"name\":\"Monthly Preventive Maintenance Schedule\",\"type\":\"excel\",\"parentId\":\"fld-schedules\",\"access\":\"All Staff\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"USER\",\"VIEWER\",\"role-super-admin\",\"role-admin\",\"role-manager\",\"role-user\",\"role-viewer\"],\"fileName\":\"Preventive_Maintenance_Schedule_2026.xlsx\",\"fileSize\":\"1.5 MB\",\"fileType\":\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\",\"description\":\"Factory-wide monthly overhaul and calibration timeline across Savar & Ashulia plants.\",\"content\":\"LINE_NAME,WEEK_1_TASK,WEEK_2_TASK,WEEK_3_TASK,WEEK_4_TASK,STATUS\\nLine JA-A,Oil Flush & Filter,Needle Bar Alignment,Motor Belt Tension,Full Cleaning,COMPLETED\\nLine JA-B,Air Jet Cleaning,Hook Lubrication,Trimmer Blade Sharpening,Sensor Calibration,IN_PROGRESS\\nLine PB-01,Overhaul 10x Juki,5x Pegasus Servicing,3x Kansai Timing,Feed Dog Height,SCHEDULED\",\"createdAt\":\"2026-08-16T10:00:00Z\",\"createdByName\":\"Engr. Delwar Hossain\"},{\"id\":\"res-6\",\"name\":\"Plant Machinery Floor Layout Map\",\"type\":\"image\",\"parentId\":\"fld-layouts\",\"access\":\"Maintenance Team\",\"accessRoles\":[\"SUPER_ADMIN\",\"ADMIN\",\"MANAGER\",\"USER\",\"role-super-admin\",\"role-admin\",\"role-manager\",\"role-user\"],\"fileName\":\"Plant_Floor_Machinery_Layout.png\",\"fileSize\":\"4.1 MB\",\"fileType\":\"image/png\",\"description\":\"High-resolution schematic showing line placements, power trunks, and pneumatic lines.\",\"content\":\"data:image/svg+xml;utf8,<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"800\\\" height=\\\"450\\\" viewBox=\\\"0 0 800 450\\\"><rect width=\\\"800\\\" height=\\\"450\\\" fill=\\\"\%230f172a\\\"/><text x=\\\"400\\\" y=\\\"50\\\" fill=\\\"\%2338bdf8\\\" font-size=\\\"20\\\" font-weight=\\\"bold\\\" text-anchor=\\\"middle\\\" font-family=\\\"sans-serif\\\">AL-MUSLIM GROUP - PLANT MACHINERY LAYOUT</text><rect x=\\\"60\\\" y=\\\"90\\\" width=\\\"310\\\" height=\\\"130\\\" fill=\\\"\%231e293b\\\" stroke=\\\"\%2338bdf8\\\" stroke-width=\\\"2\\\" rx=\\\"8\\\"/><text x=\\\"215\\\" y=\\\"130\\\" fill=\\\"\%23e2e8f0\\\" font-size=\\\"14\\\" font-weight=\\\"bold\\\" text-anchor=\\\"middle\\\" font-family=\\\"sans-serif\\\">SEWING WING A (Line JA-A to JA-C)</text><text x=\\\"215\\\" y=\\\"160\\\" fill=\\\"\%2394a3b8\\\" font-size=\\\"12\\\" text-anchor=\\\"middle\\\" font-family=\\\"sans-serif\\\">50x Lockstitch, 20x Overlock, 8x Flatlock</text><rect x=\\\"430\\\" y=\\\"90\\\" width=\\\"310\\\" height=\\\"130\\\" fill=\\\"\%231e293b\\\" stroke=\\\"\%2334d399\\\" stroke-width=\\\"2\\\" rx=\\\"8\\\"/><text x=\\\"585\\\" y=\\\"130\\\" fill=\\\"\%23e2e8f0\\\" font-size=\\\"14\\\" font-weight=\\\"bold\\\" text-anchor=\\\"middle\\\" font-family=\\\"sans-serif\\\">SEWING WING B (Line JAF-A to JAF-C)</text><text x=\\\"585\\\" y=\\\"160\\\" fill=\\\"\%2394a3b8\\\" font-size=\\\"12\\\" text-anchor=\\\"middle\\\" font-family=\\\"sans-serif\\\">45x Lockstitch, 18x Overlock, 6x Buttonhole</text><rect x=\\\"60\\\" y=\\\"250\\\" width=\\\"680\\\" height=\\\"140\\\" fill=\\\"\%231e293b\\\" stroke=\\\"\%23fbbf24\\\" stroke-width=\\\"2\\\" rx=\\\"8\\\"/><text x=\\\"400\\\" y=\\\"295\\\" fill=\\\"\%23e2e8f0\\\" font-size=\\\"14\\\" font-weight=\\\"bold\\\" text-anchor=\\\"middle\\\" font-family=\\\"sans-serif\\\">CENTRAL MAINTENANCE WORKSHOP &amp; SPARE PARTS DEPOT</text><text x=\\\"400\\\" y=\\\"330\\\" fill=\\\"\%2394a3b8\\\" font-size=\\\"12\\\" text-anchor=\\\"middle\\\" font-family=\\\"sans-serif\\\">Precision lathe, welding station, pneumatic compressor room, parts inventory</text></svg>\",\"createdAt\":\"2026-08-14T12:00:00Z\",\"createdByName\":\"Engr. Tanvir Ahmed\"}]', 13, NOW()) 
