INSERT INTO `erp_tables` (`table_name`, `raw_json`, `item_count`, `updated_at`) 
VALUES ('homepage_config', '{\"version\":\"2.6\",\"lastPublishedAt\":\"2026-09-29T03:12:02.434Z\",\"sectionOrder\":[\"hero\",\"about\",\"features\",\"modules\",\"benefits\",\"contact\",\"footer\"],\"hero\":{\"enabled\":true,\"badgeText\":\"Maintenance Department ERP\",\"badgeTag\":\"v3.8 LIVE\",\"title\":\"AL-MUSLIM GROUP\",\"titleHighlight\":\"MAINTENANCE DEPARTMENT ERP\",\"subtitle\":\"Maintenance Department ERP System\",\"description\":\"Manage machine inventory, machine transfers, spare parts replacement, manpower allocation, and complete equipment lifetime history from one centralized system across all manufacturing floors and production units.\",\"primaryBtnText\":\"User Login\",\"primaryBtnAction\":\"login\",\"secondaryBtnText\":\"Explore Machine Registry\",\"secondaryBtnAction\":\"inventory\",\"showLiveMetrics\":true},\"about\":{\"enabled\":true,\"title\":\"Engineered for Heavy Garments & Apparel Plants\",\"subtitle\":\"System Architecture & Capabilities\",\"description\":\"Designed specifically for Al-Muslim Group composite knit, woven, and denim factories. The platform bridges mechanical maintenance teams, floor supervisors, store managers, and industrial engineering departments.\",\"stats\":[{\"label\":\"Factory Units Connected\",\"value\":\"4 Factories\",\"icon\":\"🏭\"},{\"label\":\"Active Sewing & Specialized Lines\",\"value\":\"38 Lines\",\"icon\":\"🧵\"},{\"label\":\"Uptime Reliability Index\",\"value\":\"99.4\%\",\"icon\":\"⚡\"},{\"label\":\"Barcode Scanning Accuracy\",\"value\":\"100\%\",\"icon\":\"🏷️\"}]},\"features\":{\"enabled\":true,\"title\":\"Core System Capabilities\",\"subtitle\":\"State-of-the-Art Factory Operations\",\"items\":[{\"id\":\"feat-1\",\"icon\":\"📦\",\"title\":\"7-Level Machinery Catalog\",\"description\":\"Complete physical machine asset register with group, unit, floor, line, brand, model, and barcode tag tracking.\",\"status\":\"ACTIVE\",\"order\":1},{\"id\":\"feat-2\",\"icon\":\"🔄\",\"title\":\"Relocation & Transfer Ledger\",\"description\":\"Multi-level workflow approval engine for inter-floor, inter-factory, and external repair machine movements.\",\"status\":\"ACTIVE\",\"order\":2},{\"id\":\"feat-3\",\"icon\":\"⚙️\",\"title\":\"Spare Parts Replacement Matrix\",\"description\":\"Inventory tracking, fitted part histories, minimum stock warnings, and automated parts consumption ledger.\",\"status\":\"ACTIVE\",\"order\":3},{\"id\":\"feat-4\",\"icon\":\"👥\",\"title\":\"Workforce & Manpower Placement\",\"description\":\"Registry of mechanics, senior technicians, and floor line supervisors with custom skill grades and leave tracking.\",\"status\":\"ACTIVE\",\"order\":4},{\"id\":\"feat-5\",\"icon\":\"📜\",\"title\":\"Digital Machine Passport\",\"description\":\"Complete lifetime lifecycle logs documenting every service, breakdown, line transfer, and spare part replacement.\",\"status\":\"ACTIVE\",\"order\":5},{\"id\":\"feat-6\",\"icon\":\"📊\",\"title\":\"Excel Import / Export Hub\",\"description\":\"Instant roster and inventory upload/download in Microsoft Excel format with real-time error auditing.\",\"status\":\"ACTIVE\",\"order\":6}]},\"modules\":{\"enabled\":true,\"title\":\"Integrated ERP Modules\",\"subtitle\":\"Explore the Complete Suite of Industrial Plant Systems\",\"items\":[{\"id\":\"mod-1\",\"icon\":\"📦\",\"name\":\"Machine Inventory\",\"description\":\"Search, filter, view specifications, status badges, and barcode labels for all plant machinery.\",\"badge\":\"Core Asset\",\"targetView\":\"inventory\",\"status\":\"ACTIVE\",\"order\":1},{\"id\":\"mod-2\",\"icon\":\"👥\",\"name\":\"Manpower Management\",\"description\":\"Workforce roster, employee relocations, dynamic parameters, and attendance records.\",\"badge\":\"Workforce\",\"targetView\":\"manpower\",\"status\":\"ACTIVE\",\"order\":2},{\"id\":\"mod-3\",\"icon\":\"🔄\",\"name\":\"Machine Transfers\",\"description\":\"Transfer request authorization, floor movement records, and printed gate passes.\",\"badge\":\"Operations\",\"targetView\":\"transfers\",\"status\":\"ACTIVE\",\"order\":3},{\"id\":\"mod-4\",\"icon\":\"⚙️\",\"name\":\"Spare Parts Management\",\"description\":\"Central parts stock, supplier catalog, price history, and machine replacement tracking.\",\"badge\":\"Maintenance\",\"targetView\":\"spare-parts\",\"status\":\"ACTIVE\",\"order\":4},{\"id\":\"mod-5\",\"icon\":\"📜\",\"name\":\"Machine Lifetime History\",\"description\":\"Chronological timeline of all repair services, relocations, and installed spare parts.\",\"badge\":\"Lifecycle\",\"targetView\":\"machine-history\",\"status\":\"ACTIVE\",\"order\":5},{\"id\":\"mod-6\",\"icon\":\"📊\",\"name\":\"Reports & Analytics Hub\",\"description\":\"Machine uptime reports, transfer audits, parts consumption sheets, and Excel exports.\",\"badge\":\"Executive\",\"targetView\":\"reports\",\"status\":\"ACTIVE\",\"order\":6}]},\"benefits\":{\"enabled\":true,\"title\":\"Enterprise Factory Benefits\",\"subtitle\":\"Driving Higher Machine OEE & Zero Downtime\",\"items\":[{\"icon\":\"🛡️\",\"title\":\"Zero Lost Assets\",\"description\":\"Every single sewing machine, overlock, lockstitch, and cutting unit is assigned a unique digital ID and floor barcode.\"},{\"icon\":\"⏱️\",\"title\":\"70\% Faster Breakdown Response\",\"description\":\"Floor supervisors instantly log service requests directly to dedicated line mechanics.\"},{\"icon\":\"💰\",\"title\":\"Optimized Spare Parts Consumption\",\"description\":\"Eliminate duplicate spare parts purchases by tracking real lifetime consumption and part replacement frequency.\"},{\"icon\":\"📈\",\"title\":\"Complete Audit Transparency\",\"description\":\"Immutable historical logs of every relocation, approval, user activity, and maintenance action.\"}]},\"contact\":{\"enabled\":true,\"title\":\"Factory Support & Maintenance Bay\",\"subtitle\":\"Central Engineering & IT Systems Helpdesk\",\"phone\":\"9666777879\",\"email\":\"md@pacificbluejeans.com\",\"location\":\"14 Gedda. Karnapara, Ulail, Savar, Dhaka 1340, Bangladesh\",\"hours\":\"24/7 Production Floor Support & Maintenance Bay\"},\"footer\":{\"enabled\":true,\"companyName\":\"Al-Muslim Group\",\"copyrightText\":\"© 2026 Al-Muslim Group Maintenance Department ERP. All Rights Reserved.\",\"creditPrefix\":\"Developed by\",\"creditName\":\"Engr. Motaher Hossain\",\"creditUrl\":\"https://al-muslim.com\",\"showCredit\":true,\"systemVersion\":\"v3.8 Enterprise Edition\"},\"updatedAt\":\"2026-09-29T03:12:02.434Z\"}', 1, NOW()) 
ON DUPLICATE KEY UPDATE `raw_json` = VALUES(`raw_json`), `item_count` = VALUES(`item_count`), `updated_at` = NOW();

